INSERT INTO `courses` (`course_id`, `course_name`, `course_description`, `course_code`, `lec`, `lab`, `department_id`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 'Introduction to Computing', 'An introductory course to computing, covering basic computer systems and applications.', 'DCSN01C', 2, 1, 1, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(2, 'Computer Programming 1', 'This course introduces programming concepts and techniques in a structured programming environment.', 'DCSN02C', 2, 1, 1, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(3, 'Mathematics In the Modern World', 'Focus on mathematical principles that are used in everyday life and in various modern fields.', 'MATH01G', 3, 0, 5, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(4, 'Understanding the Self', 'A course designed to explore personal identity, self-awareness, and the human experience.', 'UTSN0IG', 3, 0, 3, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(5, 'Ethics', 'Introduction to the principles of ethics, moral philosophy, and contemporary ethical issues.', 'ESTN01G', 3, 0, 6, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(6, 'JPL Life and His Works', 'Study of the life and works of J.P. Lang, focusing on his contributions to science and literature.', 'JPLN01G', 3, 0, 5, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(7, 'Physical Activities Toward Health and Fitness 1', 'A physical education course designed to promote health and fitness through physical activities.', 'PATHFit1', 2, 0, 4, '2025-04-23 17:15:23', '2025-04-23 17:41:07', NULL),
(8, 'National Service Training Program 1', 'A course aimed at fostering civic consciousness and defense preparedness through community service and military training.', 'NSTPN01G', 3, 0, 7, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(9, 'Quality Consciousness, Processes and Habits', 'A course that explores quality assurance, process improvement, and establishing good work habits.', 'CPHN0IC', 3, 0, 7, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(10, 'Computer Programming 2', 'This course continues the study of programming with an emphasis on algorithms, data structures, and advanced programming concepts.', 'DCSN03C', 2, 1, 1, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(11, 'Discrete Structures 1', 'Introduction to discrete mathematical structures used in computer science, such as sets, graphs, and combinatorics.', 'CSCN01C', 3, 0, 1, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(12, 'Social Issues and Professional Practice', 'A course that explores the social, ethical, and legal issues related to the practice of computing and technology professions.', 'DCSN07C', 3, 0, 1, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(13, 'The Contemporary World', 'Study of global issues and how they affect modern society, politics, and economics.', 'TCWN01G', 3, 0, 5, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(14, 'Purposive Communication', 'Course focused on effective communication skills across various media, emphasizing purpose-driven communication in professional and personal contexts.', 'ENGL0IG', 3, 0, 3, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(15, 'Pre-Calculus and Functional Mathematics', 'A preparatory mathematics course that covers functions, algebra, and the basic concepts necessary for calculus.', 'MATN07G', 3, 0, 5, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(16, 'Living in the IT Era', 'Course that focuses on the role of information technology in everyday life and the workplace, including its impact on society and individuals.', 'LVTN01C', 3, 0, 1, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(17, 'Physical Activities Toward Health and Fitness 2', 'Continued physical education focusing on advanced activities aimed at improving fitness and health.', 'PATHFit2', 2, 0, 4, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(18, 'National Service Training Program 2', 'Continuation of the National Service Training Program (NSTP) that emphasizes civic duty and community involvement.', 'NSTPN02G', 3, 0, 7, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(19, 'Drawing 1: Basic Form and Shape', 'An introductory course focusing on the basic principles of drawing, with emphasis on form, shape, and basic techniques.', 'ARTN01G', 2, 1, 6, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(20, 'Introduction to Multimedia Arts', 'An introductory course on multimedia arts, exploring graphic design, animation, and video production techniques.', 'BMMA01F', 2, 1, 2, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(21, 'History of Graphic Design', 'A course covering the history and evolution of graphic design, from its origins to modern developments.', 'BMMA02F', 3, 0, 2, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(22, 'Science, Technology and Society', 'A course exploring the interaction between science, technology, and society, with a focus on their impact on modern life.', 'STSN11G', 3, 0, 5, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(23, 'Kontekstwalisadong Komunikasyon Sa Filipino', 'A Filipino course focusing on contextualized communication and the use of Filipino in various real-world settings.', 'FLIN01G', 3, 0, 2, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(24, 'Data Structures and Algorithms', 'A course that covers the essential concepts of data structures and algorithms, essential for efficient programming.', 'DCSN04C', 2, 1, 1, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(25, 'Object Oriented Programming', 'An including classes, objects, inheritance, and polymorphism.', 'CSCN02C', 2, 1, 1, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(26, 'Discrete Structures 2', 'A continuation of Discrete Structures 1, focusing on more advanced topics in mathematics and logic for computer science.', 'CSCN03C', 3, 0, 1, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(27, 'CS Elective 1', 'A Computer Science elective course offering students an opportunity to dive into specialized topics of their interest in CS.', 'CSELCO1C', 2, 1, 1, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(28, 'Differential and Integral Calculus', 'A math course covering the fundamentals of differential and integral calculus, essential for many fields of engineering and computer science.', 'MATH23E', 3, 0, 5, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(29, 'Art Appreciation', 'A course that introduces students to the appreciation of visual arts and their cultural significance.', 'HUMNO2G', 3, 0, 5, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(30, 'Life and Works of Rizal', 'A course examining the life and works of Dr. Jose Rizal, the national hero of the Philippines.', 'LWRNDIG', 3, 0, 4, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(31, 'Physical Activities Toward Health and Fitness 3', 'A physical education course focused on advanced fitness activities to promote health and well-being.', 'PATHFit3', 2, 0, 4, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(32, 'Algorithms and Complexity', 'This course explores the design, analysis, and complexity of algorithms, focusing on efficient problem-solving techniques and computational limits.', 'CSCN04C', 3, 0, 1, '2025-04-23 17:23:20', '2025-04-23 17:23:20', NULL),
(33, 'CS Elective 2', 'This course offers advanced topics in computer science, allowing students to specialize in areas such as machine learning, artificial intelligence, or cybersecurity, depending on their interests and career goals.', 'CSELC02C', 2, 1, 1, '2025-04-23 17:24:19', '2025-04-23 17:24:19', NULL),
(34, 'Readings in Philippine History', 'This course examines key events, figures, and social movements in Philippine history through selected readings, encouraging critical analysis of the nation\'s past and its impact on contemporary society.', 'RPHS01G', 3, 0, 6, '2025-04-23 17:25:10', '2025-04-23 17:25:10', NULL),
(35, 'Probability and Statistics', 'This course introduces the principles of probability theory and statistical methods, focusing on data analysis, probability distributions, hypothesis testing, and the application of statistical tools to solve real-world problems.', 'PSTN01E', 3, 0, 1, '2025-04-23 17:25:59', '2025-04-23 17:25:59', NULL),
(36, 'Reading Visual Art', 'This course explores the interpretation and analysis of visual art, focusing on understanding artistic styles, cultural contexts, and the impact of art on society through critical readings and discussions.', 'RVAN01G', 3, 0, 6, '2025-04-23 17:26:32', '2025-04-23 17:26:32', NULL),
(37, 'Physical Activities Toward Health and Fitness 4', 'This course focuses on advanced physical fitness activities, promoting lifelong health and well-being through exercise routines, wellness practices, and an understanding of the importance of physical activity in overall health.', 'PATHFit4', 2, 0, 4, '2025-04-23 17:27:31', '2025-04-23 17:41:57', NULL),
(38, 'Automata and Language Theory', 'This course covers the theoretical foundations of automata, formal languages, and computational models, focusing on finite automata, context-free grammars, Turing machines, and their applications in language recognition and processing.', 'CSCN05C', 3, 0, 1, '2025-04-23 17:28:06', '2025-04-23 17:28:06', NULL),
(39, 'Application Development and Emerging Technologies', 'This course explores the development of modern applications using emerging technologies, emphasizing programming practices, software development frameworks, and the integration of innovative tools like AI, cloud computing, and blockchain.', 'DSCN06C', 2, 1, 1, '2025-04-23 17:28:41', '2025-04-23 17:28:41', NULL),
(40, 'Accounting Information System', 'This course examines the design, implementation, and management of information systems used in accounting, focusing on the integration of technology to improve financial reporting, auditing, and decision-making processes.', 'ICTN04C', 2, 1, 7, '2025-04-23 17:29:08', '2025-04-23 17:29:08', NULL),
(41, 'Software Engineering 1', 'This course introduces the principles of software engineering, covering software development life cycles, requirements analysis, system design, and project management, with an emphasis on creating high-quality, maintainable software.', 'CSCN10C', 2, 1, 1, '2025-04-23 17:29:34', '2025-04-23 17:29:34', NULL),
(42, 'Architecture and Organization', 'This course covers the fundamental concepts of computer architecture and organization, including the structure and operation of computer systems, memory hierarchy, instruction sets, and the role of hardware components in executing software.', 'CSCN07C', 2, 1, 1, '2025-04-23 17:30:06', '2025-04-23 17:30:06', NULL),
(43, 'Information Assurance and Security', 'This course focuses on the principles and practices of securing information systems, including topics like cryptography, network security, risk management, and the development of strategies to protect data integrity, confidentiality, and availability.', 'CSCN08C', 2, 1, 1, '2025-04-23 17:30:43', '2025-04-23 17:31:06', NULL),
(45, 'Quantitative Methods', 'This course covers statistical and mathematical techniques for data analysis, decision-making, and problem-solving, focusing on methods such as regression analysis, probability theory, and optimization for real-world applications in business and science.', 'ITEN04C', 3, 0, 1, '2025-04-23 17:31:39', '2025-04-23 17:31:39', NULL),
(46, 'Programming Language', 'This course explores the design, syntax, and semantics of programming languages, examining various paradigms such as imperative, object-oriented, and functional programming, along with the principles behind language implementation and compilers.', 'CSCN09C', 2, 1, 1, '2025-04-23 17:32:12', '2025-04-23 17:32:12', NULL),
(47, 'Software Engineering 2', 'This course builds on Software Engineering 1, focusing on advanced software development techniques, including system architecture, design patterns, testing, debugging, and the application of agile methodologies in real-world software projects.', 'CSCN13C', 2, 1, 1, '2025-04-23 17:32:37', '2025-04-23 17:32:37', NULL),
(48, 'Operating Systems', 'This course covers the fundamental concepts of operating systems, including process management, memory management, file systems, and system security, with an emphasis on how operating systems manage hardware resources and provide a platform for software applications.', 'CSCN12C', 2, 1, 1, '2025-04-23 17:33:02', '2025-04-23 17:33:02', NULL),
(49, 'CS Elective 3', 'This course offers specialized topics in computer science, allowing students to explore areas such as data science, advanced algorithms, or software development, based on their academic and professional interests.', 'CSELC03C', 2, 1, 1, '2025-04-23 17:33:26', '2025-04-23 17:33:26', NULL),
(50, 'Research Methods and Computing', 'This course introduces students to research methodologies in computing, emphasizing the design, execution, and analysis of research projects, along with the use of computational tools and techniques for data collection, analysis, and presentation.', 'RMCN01C', 3, 0, 1, '2025-04-23 17:34:00', '2025-04-23 17:34:00', NULL),
(51, 'Advanced Holistic Professional Development', 'This course focuses on the development of advanced professional skills, emphasizing leadership, communication, ethics, and personal growth, to prepare students for success in dynamic work environments and to foster a well-rounded approach to career advancement.', 'AHPD01E', 3, 0, 3, '2025-04-23 17:34:43', '2025-04-23 17:34:43', NULL),
(52, 'Thesis Writing 1', 'This course guides students through the initial stages of their thesis, focusing on research topic selection, literature review, research design, and methodology, laying the foundation for the development of a comprehensive and well-structured thesis.', 'THEL01C', 3, 0, 1, '2025-04-23 17:35:34', '2025-04-23 17:35:34', NULL),
(53, 'CS Elective 4', 'This course offers advanced topics in computer science, providing students with the opportunity to explore specialized areas such as artificial intelligence, machine learning, or cloud computing, based on their career goals and academic interests.', 'CSELC04C', 2, 1, 1, '2025-04-23 17:36:07', '2025-04-23 17:36:07', NULL),
(54, 'Introduction to Human Computer Interactions', 'This course explores the principles of human-computer interaction (HCI), focusing on the design, evaluation, and implementation of user interfaces to improve the usability, accessibility, and overall experience of interacting with computer systems.', 'ITEN01C', 2, 1, 1, '2025-04-23 17:36:45', '2025-04-23 17:36:45', NULL),
(55, 'IT Trips and Seminars', 'This course involves attending industry-related trips and seminars, providing students with opportunities to engage with professionals, learn about current trends in information technology, and gain practical insights into the IT industry.', 'ITSN01C', 3, 0, 1, '2025-04-23 17:37:12', '2025-04-23 17:37:12', NULL),
(56, 'Thesis Writing 2', 'This course focuses on the completion of the thesis, guiding students through data analysis, discussion of results, and the writing of the final thesis document, with an emphasis on presenting research findings and preparing for thesis defense.', 'THEL02C', 3, 0, 1, '2025-04-23 17:37:45', '2025-04-23 17:37:45', NULL),
(57, 'Technopreneurship', 'This course explores the principles of entrepreneurship in the tech industry, focusing on the creation, development, and management of technology-based startups, along with strategies for innovation, funding, and scaling tech ventures.', 'TPRN01E', 3, 0, 1, '2025-04-23 17:38:11', '2025-04-23 17:38:11', NULL),
(58, 'Foreign Language', 'This course introduces students to the basics of a foreign language, focusing on vocabulary, grammar, speaking, listening, reading, and writing skills, with an emphasis on practical communication and cultural understanding.', 'FLAN01G', 3, 0, 6, '2025-04-23 17:38:35', '2025-04-23 17:38:35', NULL),
(59, 'Information Management', 'This course covers the principles and practices of managing information systems, focusing on data collection, storage, retrieval, and analysis, as well as the strategic use of information technology to support organizational decision-making and business operations.', 'DSCN05C', 2, 1, 1, '2025-04-23 17:48:13', '2025-04-23 17:48:13', NULL),
(60, 'Networks and Communication', 'This course covers the fundamentals of computer networks and communication systems, focusing on network protocols, data transmission, wireless technologies, and the principles of designing and managing secure and efficient network infrastructures.', 'CSCN15C', 2, 1, 1, '2025-04-23 17:53:09', '2025-04-23 17:53:09', NULL);
