INSERT INTO `departments` (`department_id`, `department_name`, `department_description`, `department_code`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 'College of Engineering, Computer Studies and Architecture', 'Combining technical skills with creative design, this college prepares students for careers in engineering, IT, and architecture. It emphasizes innovation, problem-solving, and practical applications.', 'COECSA', '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(2, 'College of Fine Arts and Design', 'This college nurtures artistic talent and creativity, offering programs in visual arts, graphic design, and multimedia. Students develop a solid foundation in artistic expression and technical skills.', 'CFAD', '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(3, 'College of International Tourism and Hospitality Management', 'Focused on global hospitality and tourism, this college equips students with the skills to manage hotels, resorts, and travel services. Programs emphasize cultural sensitivity, customer service, and industry trends.', 'CITHM', '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(4, 'College of Nursing', 'Dedicated to training compassionate and skilled nurses, this college emphasizes patient care, clinical skills, and ethical practice. Graduates are prepared to excel in various healthcare settings and provide high-quality nursing care.', 'CON', '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(5, 'College of Allied Medical Sciences', 'The College of Allied Medical Sciences (CAMS) provides education and training in various healthcare fields, preparing students for careers in medical technology, physical therapy, nursing, and other allied health professions. It emphasizes hands-on learning and healthcare excellence.', 'CAMS', '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(6, 'College of Liberal Arts and Education', 'Offers a diverse range of programs focused on critical thinking, creativity, and communication. It prepares students for careers in education, social sciences, humanities, and the arts, fostering a well-rounded, socially responsible approach to learning.', 'CLAE', '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(7, 'College of Business Administration', 'Department dedicated to the design, construction, and operation of machinery and mechanical systems.The College of Business Administration (CBA) equips students with essential business skills in management, finance, and marketing, preparing them for leadership roles in the global business world.', 'CBA', '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL);
