INSERT INTO `programs` (`program_id`, `uuid`, `program_code`, `program_name`, `abbreviation`, `program_description`, `department_id`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, '8af7a975-2066-11f0-8540-b06ebf3a05f9', 'BSMT', 'BS Medical Technology', 'MT', 'Focuses on laboratory sciences, training students in clinical procedures and diagnostics used to detect, diagnose, and treat diseases.', 5, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(2, '8af7e1f4-2066-11f0-8540-b06ebf3a05f9', 'BS-PHAR', 'BS Pharmacy', 'PH', 'Prepares students for careers in the pharmaceutical industry, emphasizing drug therapy, patient care, and medication management.', 5, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(3, '8af7e31d-2066-11f0-8540-b06ebf3a05f9', 'BS-RADTECH', 'BS Radiologic Technology', 'RT', 'Trains students in medical imaging techniques, including X-ray, MRI, and CT scans, to assist in patient diagnosis.', 5, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(4, '8af7e453-2066-11f0-8540-b06ebf3a05f9', 'BS-BIO', 'BS Biology', 'BIO', 'Provides a broad understanding of biological sciences, covering genetics, ecology, and microbiology as foundations for careers in research, healthcare, and biotechnology.', 5, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(5, '8af7e4d9-2066-11f0-8540-b06ebf3a05f9', 'B-COM', 'Bachelor of Arts in Communication', 'BACOMM', 'Focuses on communication theory, media studies, and public relations, preparing students for careers in journalism, media, and corporate communication.', 6, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(6, '8af7e557-2066-11f0-8540-b06ebf3a05f9', 'AB-FS', 'AB Foreign Service', 'ABFS', 'Prepares students for diplomatic careers with training in international relations, global politics, and cultural studies.', 6, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(7, '8af7e5c8-2066-11f0-8540-b06ebf3a05f9', 'AB-LS', 'AB Legal Studies', 'ABLS', 'Offers foundational legal knowledge and critical thinking skills, ideal for students aiming for law school or legal assistant roles.', 6, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(8, '8af7e6b3-2066-11f0-8540-b06ebf3a05f9', 'BECE', 'Bachelor of Early Childhood Education', 'ECED', 'Equips students with teaching methods and psychology for educating young children, particularly in preschool and elementary levels.', 6, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(9, '8af7e72a-2066-11f0-8540-b06ebf3a05f9', 'BSE', 'Bachelor in Secondary Education', 'SED', 'Prepares future educators to teach at the secondary level, specializing in pedagogy and adolescent development.', 6, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(10, '8af7e79c-2066-11f0-8540-b06ebf3a05f9', 'BS-PSYCH', 'BS Psychology', 'PSYCH', 'Covers psychological theories and practices, preparing students for roles in counseling, human resources, or further studies in psychology.', 6, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(11, '8af7e80e-2066-11f0-8540-b06ebf3a05f9', 'BSA', 'BS Accountancy', 'ACC', 'Provides expertise in financial accounting, taxation, and auditing, essential for roles as accountants or financial analysts.', 7, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(12, '8af7e87d-2066-11f0-8540-b06ebf3a05f9', 'BA-HRM', 'BS Business Administration major in Human Resource Development Management', 'HRM', 'Trains students in managing employee relations, talent acquisition, and organizational behavior.', 7, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(13, '8af7e8ee-2066-11f0-8540-b06ebf3a05f9', 'BA-MA', 'BS Business Administration major in Management Accounting', 'MA', 'Equips students with skills in budgeting, cost management, and financial planning within organizations.', 7, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(14, '8af7e9f4-2066-11f0-8540-b06ebf3a05f9', 'BA-MM', 'BS Business Administration major in Marketing Management', 'MM', 'Focuses on marketing strategies, consumer behavior, and brand management, preparing students for marketing careers.', 7, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(15, '8af7ea69-2066-11f0-8540-b06ebf3a05f9', 'BA-OM', 'BS Business Administration major in Operations Management', 'OM', 'Teaches principles of production, logistics, and supply chain management to streamline business processes.', 7, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(16, '8af7eaf9-2066-11f0-8540-b06ebf3a05f9', 'BSCA', 'BS Customs Administration', 'CA', 'Prepares students for careers in customs, trade compliance, and logistics within global supply chains.', 7, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(17, '8af7eb7a-2066-11f0-8540-b06ebf3a05f9', 'BS-ENTR-AI', 'BS Entrepreneurship with specialization in Aesthetics Industry Management', 'ENTREP', 'Focuses on business startup processes and managing ventures specifically within the aesthetics and wellness industry.', 7, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(18, '8af7ebf7-2066-11f0-8540-b06ebf3a05f9', 'BSREM', 'BS Real Estate Management', 'REM', 'Provides knowledge in real estate laws, property management, and market analysis, preparing students for roles in real estate.', 7, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(19, '8af7ec70-2066-11f0-8540-b06ebf3a05f9', 'BS-ARCH', 'Bachelor of Science in Architecture', 'ARCH', 'Teaches design principles, architectural theory, and construction techniques for careers in architecture.', 1, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(20, '8af8674a-2066-11f0-8540-b06ebf3a05f9', 'BSCS', 'BS Computer Science', 'CS', 'Computer Science will be able to learn about other subjects such as machine learning, blockchain, social hacking, and data analytics.', 1, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(21, '8af8682d-2066-11f0-8540-b06ebf3a05f9', 'BSIT', 'BS Information Technology', 'IT', 'Equips students with the basic ability to conceptualize, design, and implement software applications.', 1, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(22, '8af868bf-2066-11f0-8540-b06ebf3a05f9', 'LIS', 'Bachelor of Library and Information Science', 'LIS', 'Trains students in library management, information retrieval, and cataloging, preparing them for roles in library sciences.', 1, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(23, '8af86946-2066-11f0-8540-b06ebf3a05f9', 'BSAE', 'Bachelor of Science in Aeronautical Engineering', 'ENG', 'Prepares students for the aviation industry with training in aircraft design, systems, and safety.', 1, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(24, '8af869d4-2066-11f0-8540-b06ebf3a05f9', 'BSCE', 'BS Civil Engineering', 'CE', 'Designed to prepare graduates to apply knowledge of mathematics, calculus-based physics, chemistry, and at least one additional area of basic science.', 1, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(25, '8af86a54-2066-11f0-8540-b06ebf3a05f9', 'BSCPE', 'BS Computer Engineering', 'CPE', 'Focuses on the development and optimization of both computer hardware and software.', 1, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(26, '8af86ad6-2066-11f0-8540-b06ebf3a05f9', 'BET-CTM', 'Bachelor of Engineering Technology', 'ET', 'Teaches construction practices and project management in engineering settings.', 1, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(27, '8af86b4c-2066-11f0-8540-b06ebf3a05f9', 'BSECE', 'BS in Electronics Engineering', 'EE', 'Focuses on electronic devices, telecommunications, and signal processing.', 1, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(28, '8af86bc4-2066-11f0-8540-b06ebf3a05f9', 'BSIE', 'Bachelor of Science in Industrial Engineering', 'IE', 'Teaches process optimization, production planning, and quality control in various industries.', 1, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(29, '8af86c49-2066-11f0-8540-b06ebf3a05f9', 'BSME', 'BS Mechanical Engineering', 'ME', 'Covers thermodynamics, mechanical design, and manufacturing processes for engineering roles.', 1, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(30, '8af86cc5-2066-11f0-8540-b06ebf3a05f9', 'BFA', 'Bachelor of Fine Arts', 'FA', 'Offers creative training in painting, sculpture, and visual arts for careers in the arts sector.', 2, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(31, '8af86d42-2066-11f0-8540-b06ebf3a05f9', 'BMMA', 'Bachelor of Multimedia Arts', 'MMA', 'Combines digital media, graphic design, and animation, preparing students for multimedia industries.', 2, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(32, '8af86dc3-2066-11f0-8540-b06ebf3a05f9', 'B-PHOTO', 'Bachelor in Photography', 'PHOTO', 'Teaches photography techniques and visual storytelling for careers in professional photography.', 1, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(33, '8af86e47-2066-11f0-8540-b06ebf3a05f9', 'BS-ITTM', 'BS International Travel and Tourism Management', 'TM', 'Prepares students for roles in tourism management, including travel planning and tour operations.', 3, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(34, '8af86ec8-2066-11f0-8540-b06ebf3a05f9', 'BS-ITTM-HW', 'BS International Travel and Tourism Management (Health and Wellness)', 'TM', 'Specializes in health and wellness tourism, focusing on wellness programs and spa management.', 3, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(35, '8af86f56-2066-11f0-8540-b06ebf3a05f9', 'BSHM', 'BS International Hospitality Management', 'HM', 'Prepares students to become effective leaders, managers, and/or entrepreneurs in the global hospitality industry.', 3, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(36, '8af86fd9-2066-11f0-8540-b06ebf3a05f9', 'BSND', 'BS Nutrition and Dietetics', 'ND', 'Prepares students to become dietitians or nutritionists, focusing on meal planning and health management.', 3, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL),
(37, '8af8705b-2066-11f0-8540-b06ebf3a05f9', 'BSN', 'BS Nursing', 'NURS', 'Provides clinical and theoretical training in patient care, preparing students to become registered nurses.', 4, '2025-04-23 17:15:23', '2025-04-23 17:15:23', NULL);
